<?php namespace App\Http\Controllers; use App\Models\{Product,Supplier,Warehouse,Salesperson}; use Illuminate\Http\Request; use Illuminate\Validation\Rule; class MasterDataController extends Controller {private function meta(Request $r):array{$key=explode('.',$r->route()->getName())[0];return match($key){'products'=>[Product::class,'Produk'],'suppliers'=>[Supplier::class,'Supplier'],'warehouses'=>[Warehouse::class,'Gudang'],default=>[Salesperson::class,'Sales']};} private function rules($c,$id=null){return match($c){Product::class=>['name'=>'required|max:150','barcode'=>['required','max:100',Rule::unique('products')->ignore($id)],'code'=>['required','max:50',Rule::unique('products')->ignore($id)],'sku'=>['required','max:50',Rule::unique('products')->ignore($id)],'warehouse_id'=>'required|exists:warehouses,id','supplier_id'=>'nullable|exists:suppliers,id','unit'=>'required|max:20','cost_price'=>'required|numeric|min:0','selling_price'=>'required|numeric|min:0','minimum_stock'=>'required|integer|min:0','status'=>'required|in:active,inactive'],Supplier::class=>['name'=>'required|max:150','email'=>'nullable|email','phone'=>'nullable|max:30'],Warehouse::class=>['name'=>'required|max:150'],default=>['name'=>'required|max:150','email'=>'nullable|email','status'=>'required|in:active,inactive']};} private function context(Request $r,$row=null){[$class,$title]=$this->meta($r);return ['row'=>$row??new $class,'title'=>$title,'resource'=>explode('.',$r->route()->getName())[0],'suppliers'=>Supplier::all(),'warehouses'=>Warehouse::all()];} public function index(Request $r){[$class,$title]=$this->meta($r);$q=$class::query();if($s=$r->get('q'))$q->where('name','like',"%{$s}%");return view('master.index',['rows'=>$q->latest()->paginate(12)->withQueryString(),'title'=>$title,'resource'=>explode('.',$r->route()->getName())[0]]);} public function create(Request $r){return view('master.form',$this->context($r));} public function store(Request $r){[$class]=$this->meta($r);$data=$r->validate($this->rules($class));$class::create($data+$r->only(['pic','phone','address','city','npwp','notes','branch','area','category','brand','rack_location']));return redirect()->route(explode('.',$r->route()->getName())[0].'.index')->with('success','Data berhasil disimpan.');} public function edit(Request $r,$id){[$class]=$this->meta($r);return view('master.form',$this->context($r,$class::findOrFail($id)));} public function update(Request $r,$id){[$class]=$this->meta($r);$row=$class::findOrFail($id);$row->update($r->validate($this->rules($class,$id))+$r->only(['pic','phone','address','city','npwp','notes','branch','area','category','brand','rack_location']));return redirect()->route(explode('.',$r->route()->getName())[0].'.index')->with('success','Data diperbarui.');} public function destroy(Request $r,$id){[$class]=$this->meta($r);$class::findOrFail($id)->delete();return back()->with('success','Data diarsipkan.');}}
